"""관측·행동·보상과 시뮬레이션 시간 설정.

SIMULATION은 제어 간격과 종료 조건, OBSERVATION은 관측 구성을 정한다.
ACTION은 행동 변환과 선택 안전장치, REWARD는 스텝·종료 보상 계수다.
학습 할인율은 training/train.py의 HPARAMS에서 설정한다.
"""


# 1) 시뮬레이션 시간 설정

SIMULATION = {
    "step_length": 0.5,   # SUMO 1스텝 = 0.5초. RL의 1 timestep과 동일.
                          # 작게 하면(0.1) 제어가 정밀해지지만 에피소드가 길어지고,
                          # 크게 하면(1.0) 학습이 빨라지지만 제어가 거칠어진다.
    "max_steps": 1000,    # 에피소드 최대 스텝 수. 1000 * 0.5초 = 500초.
                          # 도로 12km를 평균 24 m/s로 달리면 약 1000스텝.
                          # 이 시간 안에 완주 못하면 truncation(시간 초과) 처리.
    "stuck_seconds": 120, # ego가 이 시간(초) 이상 계속 멈춰 있으면 "비정상 정지"로 종료 (0이면 끔)
    "wrong_lane_end_m": 0.0,   # 경로가 끊기는 차로 끝에서 조기 종료하는 거리(m). 0이면 비활성화.
    "warmup_steps": 4,    # ego 투입 전 프리필 차량들이 자리잡는 정착 스텝.
                          # (도로 전체를 채우는 일은 road_config의 prefill이
                          #  담당하므로 길게 흘릴 필요가 없다)

    # SUMO GUI 공통 설정 : GUI 확대는 여기 하나만 바꾸면 된다.
    # environment/view_road.py, train/test GUI, 데이터 수집 GUI와 생성되는 highway.gui.xml까지
    # 모두 이 값을 사용한다. 숫자가 클수록 더 가까이 확대된다.
    "gui_zoom": 4000.0,   # ego 추적 시 확대 배율(%). SUMO zoom은
                          # "네트워크 전체=100%" 기준이라 도로가 길수록
                          # 큰 값이 필요. 12km 기준 4000% ≈ 시야 300m.
                          # 도로 길이를 바꾸면 이 값도 비례해 조정할 것.
    "gui_delay": 100.0,
    "gui_view_width": 200.0,  # GUI 대기 화면에서 보여줄 도로 폭(m).
                              # 도로 시작 구간이 이 폭만큼 확대되어 보인다.
                              # (▶ 재생 후에는 gui_zoom의 ego 추적으로 전환)
    "gui_track_ego": True,
}


# 2) 관측: 기본 31차원과 경로·신호·경합 차량·제한속도 정보, 기본 구성은 49차원.
# 모든 칸은 [-1, 1]로 정규화한다. W는 visibility, vmax는 차 최고속도다.
#
# [0] 내 속도 / vmax
# 좌2·좌1·현재·우1·우2의 5개 차로, k=0..4:
#   [1+4k] 앞차 상대거리 / W, 없으면 1
#   [2+4k] 앞차 상대속도 / vmax, 없으면 1
#   [3+4k] 뒤차 상대거리 / W, 없으면 -1
#   [4+4k] 뒤차 상대속도 / vmax, 없으면 -1
# 상대거리와 상대속도의 기준은 AV다. 현재 차로 블록은 [9..12]다.
# lane_dir_obs가 켜져 있으면 나란히 있는 옆 차로 차량도 거리 0으로 기록한다.
# [21..25] 차로 연결성: 없음 -1, W 안에서 이어짐 1, 끝나면 남은 거리/W
# [26..30] 차로별 전방 밀도: W 안의 차량 수/수용 대수, 없는 차로는 1
#
# 49차원 배치 (lane_dir_obs=True):
#   [31,32] 첫 분기 방향·거리              route_dir1, route_dist1
#   [33,34] 둘째 분기 방향·거리            route_dir2, route_dist2
#   [35,36] 첫 분기에 왼쪽·오른쪽 도달 가능 reach1_left, reach1_right
#   [37,38] 둘째 분기에 왼쪽·오른쪽 도달 가능 reach2_left, reach2_right
#   [39,40,41] 신호 색·정지선 거리·남은 시간 sig_color, sig_dist, sig_time
#   [42..45] 경합 AV 거리·상대 거리·상대 속도·우선권
#   [46,47,48] 현재 제한속도·다음 제한속도·변경 지점 거리
# 43차원 배치 (lane_dir_obs=False, 기존 모델 호환):
#   [31,32] 분기 방향·거리, [33,34] 신호 색·거리, [35..38] 경합 차량
#   [39..41] 제한속도 정보, [42] 신호 남은 시간
# conflict_obs·speed_limit_obs·signal_time_obs를 끄면 해당 블록이 빠진다.
# 칸 번호 대신 sumo_env.obs_index의 이름으로 읽는다.
#
# 분기는 경로상 다음 갈림길이다. 49차원 방향은 출구를 좌우 순위로 매긴 값이다.
# 가장 왼쪽은 +1, 가장 오른쪽은 -1이며 둘째 분기도 같은 정의를 쓴다.
# 거리는 branch_horizon으로 나누고, 보이지 않으면 방향 0·거리 1이다.
# 43차원 방향은 SUMO 연결의 l/s/r을 +1/0/-1로 변환하고 route_horizon을 쓴다.
# 도달 가능 칸은 현재 차로를 그대로 따라갔을 때 나갈 수 있는 방향이다.
# 경로에 맞는 차로를 정답으로 주지 않으며, 내부 차로에서는 직전 값을 유지한다.
# 신호 색은 녹 1·황 0·적 -1, 없거나 꺼져 있으면 1이다.
# 정지선 거리와 남은 시간은 signal_horizon·signal_time_horizon으로 나눈다.
# 남은 시간이 없거나 바뀌지 않는 신호는 1로 표시한다.
# 경합 차량은 AV와 경합 지점에 도착하는 시각이 가장 가까운 차다.
# 두 거리의 기준은 conflict_horizon, 상대 속도는 vmax로 정규화한다.
# 우선권은 AV 우선 +1·양보 -1·대등 또는 없음 0이다.
# 제한속도 두 칸은 vmax, 변경 지점 거리는 route_horizon으로 나눈다.
# 다음 변경 지점이 없으면 현재 제한속도와 거리 1을 쓴다.

OBSERVATION = {
    "visibility": 50.0,          # 관측 가능 거리 W (m). 앞뒤 차량 감지와
                                 # 상대거리/연결성/밀도 정규화의 기준.
    "density_veh_length": 7.5,   # 밀도 계산 시 차량 1대의 점유 길이 (m)
                                 # = 차체(~5m) + 최소 안전간격(~2.5m).
                                 # 최대 수용 대수 = W / 이 값
    "route_horizon": 300.0,      # 경로 관측 정규화 거리 (m) : 분기 앞 차로 변경 여러 번을 준비할 거리
    "signal_horizon": 150.0,     # 신호 관측 정규화 거리 (m) : sumo_env.RED_WAIT_RANGE와 같게
    # 선택 관측 스위치 (위 주석 [35..42]). 11/17 컨설팅 뒤 켬  /  43차원.
    # 11/16 시범 · BC(results/team_bc_1116*)는 옛 39차원(차로별 경로 관측 포함)이라 새 환경에서 못 읽는다.
    "conflict_obs": True,        # 교차로 · 합류 경합 차량 4차원
    "conflict_horizon": 100.0,   #   경합 지점을 찾는 거리 (m)
    "speed_limit_obs": True,     # 차로 제한속도 3차원
    "signal_time_obs": True,     # 신호 남은 시간 1차원 (11/17)
    "signal_time_horizon": 170.0,  # s. 남은 시간 정규화 : 반포대로 신호 주기 (road_spec.SIGNALS, 잠수교는 75)
    # 분기 2개 · 차로 진행 방향 6차원 (위 주석 49차원 배치). 켜면 49차원.
    # 끄면 11/17~18의 43차원과 값이 완전히 같다 (43차원 모델 results/team_rl_1118_F2 등을 계속 평가할 수 있게).
    # 환경변수 SUMO_LANE_DIR_OBS=0 / 1로 이 값을 덮어쓸 수 있다 (sumo_env.__init__ : 43차원 모델 평가용, 평가 워커에도 전달됨).
    "lane_dir_obs": True,
    "branch_horizon": 600.0,     # m. [31..38]이 분기를 찾는 거리 (lane_dir_obs 켬일 때). 제한속도 관측은 route_horizon 그대로
}


# 3) 행동 (Action, A) : [종방향 가감속, 차선 변경] 2차원
#
# policy가 내는 원시 행동:
#   action[0] = accel ∈ [-1, 1]
#       +1: 최대 가속, 0: 속도 유지, -1: 최대 감속
#
#   action[1] = lane_raw ∈ [-1, 1]
#       환경에서 가장 가까운 {-1, 0, +1}로 양자화해서 실제 차선 명령으로 사용.
#       +1 = 왼쪽 한 차선, 0 = 현재 차선 유지, -1 = 오른쪽 한 차선
#
# PPO는 기존 Gaussian 연속정책을 그대로 유지하고 lane_raw만 환경에서 3값으로
# 양자화한다. 따라서 기존 PPO 구현을 크게 바꾸지 않고 차선변경까지 함께 학습한다.
# 데이터 수집 시에는 raw 행동과 실제 적용된 {-1,0,+1} 명령을 둘 다 저장한다.

ACTION = {

    # 차선변경 안전 게이트 (측면충돌 방지)
    #
    # 변경 명령이 와도 목표 차선의 앞뒤 간격이 아래 조건을 만족하지
    # 않으면 실행하지 않는다 ( /  invalid_action_penalty 부과):
    #   앞: gap > min_front_gap + front_tau × 내 속도
    #   뒤: gap > min_rear_gap  + rear_tau  × 후행차 속도
    # 속도 비례 항(tau)은 "빠르게 접근 중인 5m"와 "정지 상태의 5m"의
    # 위험도 차이를 반영한 시간여유 기반 판정이다.
    #
    # 이 게이트가 없으면(안전장치 OFF 환경에서) 무작위 탐험 단계의
    # 차선변경 시도 대부분이 측면충돌 즉사로 이어져, 에이전트가
    # "차선변경 = 죽음"만 학습하고 변경 자체를 포기하는 지역최적에
    # 빠진다. 게이트는 탐험을 살려두되, 종방향(추돌) 위험은 그대로
    # 남겨서 감속/차간유지 학습 신호는 유지한다.

    "lane_change_safety": {
        "enabled": True,
        #  감소  공격적 세팅: 최소한의 물리적 여유만 남기고 바짝 파고들기 허용.
        #   (기존 5.0/0.3/0.5/1.0  /  충돌이 다시 늘면 그 값으로 되돌릴 것)
        "min_front_gap": 3.0,   # m
        "min_rear_gap": 3.0,    # m
        "front_tau": 0.15,      # s (내 속도 기준)
        "rear_tau": 0.3,        # s (후행차 속도 기준)
        "approach_horizon": 0.6,  # s. 접근 여유 판정 시간 : "이 시간 안에
                                  # 상대와 만나면 위험". 짧을수록 공격적.
        "spawn_protect": 60.0,  # m. 도로 시작 이 구간 안에서는 변경 금지.
                                # flow가 입구에서 새 차를 만드는데 "생성 직전"
                                # 차량은 관측 불가라 원천 사각지대이기 때문.
    },


    # 안전장치 스위치 : 최소 충돌 방지 제동만 (RL 모드에서만)
    # 정책 속도 명령이 "같은 차로 앞차 뒤에 최대 감속(EGO decel)으로 설 수 있는 속도"를 넘으면 그 속도로 낮춘다.
    # 판단(가감속 · 차로 · 신호)은 신경망이 하고 이것은 하위 제어 보호막이다. 11/17 컨설팅에서 불허  /  끈 채로 학습 · 평가 · 공개.
    # (11/16 BC 켬/끔 비교 수치의 근거라 코드는 남긴다.)

    "safety_brake": {
        "enabled": False,       # 기본 끔 (수업 원본과 같은 조건). 11/17 컨설팅: 안전장치 불허  /  켜지 않는다
        "min_gap": 2.0,         # m. 앞차 뒤에 남길 최소 간격
        "lookahead": 100.0,     # m. 앞차를 찾는 거리
    },

    "dim": 2,
    "accel_index": 0,
    "lane_change_index": 1,
    "lane_change_values": (-1, 0, 1),
    "lane_change_threshold": 0.5,   # raw <= -0.5 / -1, >=+0.5 / +1, 그 사이 / 0
    "lane_change_duration": 1.0,    # SUMO에 차선 변경 명령을 유지하는 시간(초)
}


# 4) 보상 (Reward, R)
#
# 매 스텝 보상 = speed_weight * min(현재속도 / 지금 차로 제한속도, 1)     빠를수록 + (12팀 11/15: vmax  /  차로 제한속도)
#              - overspeed_weight * max(0, 현재속도 / 지금 차로 제한속도 - 1)    과속 감점 (12팀 11/24)
#              - close_gap_penalty (간격 < threshold 일 때)   위험운전 벌점
#                (close_gap_headway > 0이면 간격 < close_gap_headway × 내 속도 일 때)
#              - ttc_penalty × clip(ttc_threshold / TTC, 1, ttc_max_scale) (TTC < ttc_threshold 일 때)    12팀 11/18
#              - red_far_stop_penalty (적색 신호 앞 정지선 · 앞차와 red_far_stop_gap 넘게 떨어져 서 있을 때)    12팀 11/18
#              - blocked_penalty · 차로 변경 감점 (아래)
# 종료 보상   = -collision_penalty (충돌)  또는  +arrival_bonus (완주)
#
# 설계 의도:
#   속도 보상만 있으면 "무조건 밟는" 정책이 나와 충돌한다.
#   충돌 벌점만 크면 "겁먹고 서 있는" 정책이 나온다.
#   이 둘 사이 균형을 잡는 것이 보상 설계(reward shaping)의 핵심이며,
#   아래 숫자들을 바꿔가며 정책이 어떻게 달라지는지 관찰해보길 권장.

REWARD = {
    "speed_weight": 0.1,         # 속도 보상 가중치. 한 스텝 최대 +0.1
    "overspeed_weight": 0.5,     # 과속 감점 = 이 값 × max(0, 속도 / 차로 제한속도 − 1). 10% 과속이면 스텝당 −0.05.
                                 #   환경이 제한속도로 속도 명령을 자르지 않게 바꾸면서(조교 게시판 14조 4번 답) 추가. 데이터 reward와
                                 #   맞아야 하므로 학습마다 바꾸지 않는다
    "close_gap_threshold": 6.0, # 앞차와 이 거리(m) 미만으로 붙으면 (좁게 따라붙기 허용:
                                 #  10 / 6m 완화. 추월 직전 대기 위치를 잡기 쉬워짐)
    "close_gap_penalty": 0.1,    #    /  스텝당 이만큼 감점
    "close_gap_min_speed": 5.0,  # 이 속도(m/s) 이상으로 달릴 때만 근접 감점 : 신호 대기열 정지(간격 2 m)는 정상
                                 #   (evaluation/metrics.py 최소 간격도 5 m/s 이상만 셈). 0이면 수업 원본대로 항상
    "ttc_threshold": 2.0,        # 같은 차로 앞차와 충돌까지 남은 시간(간격 / 접근 속도)이 이 값(초) 미만이면
    "ttc_penalty": 0.0,          #    /  스텝당 이만큼 감점 (속도 무관). 0이면 끔. 값은 training/train.py에서 정한다.
    "ttc_max_scale": 1.0,        # 감점 = ttc_penalty × clip(ttc_threshold / TTC, 1, 이 값). 1이면 고정 감점(이전과 같음)
    "close_gap_headway": 0.0,    # 초. > 0이면 근접 판정을 간격 < 이 값 × 내 속도로 (close_gap_threshold 대신). 0이면 거리 기준
    "red_far_stop_penalty": 0.0, # 적색 신호(150 m 안) 앞에서 1 m/s 미만으로 서 있는데 정지선 · 같은 차로 앞차가 모두
    "red_far_stop_gap": 15.0,    #   이 거리(m)보다 멀면 스텝당 감점. 정지선 앞 교차로 · 합류에 경합 차량이 있으면(양보 대기) 제외. 0이면 끔
    "collision_penalty": 5.0,    # 충돌 시 -5 를 받고 에피소드 즉시 종료
    "arrival_bonus": 2.0,        # 도로 끝까지 완주하면 +2 받고 종료

    # ---- 막힘(blocked) 페널티: 추월 학습의 핵심 신호 ----
    # "느린 앞차에 막혀 있는 상태"에 매 스텝 감점을 준다.
    #   조건: 같은 차선 앞차가 blocked_gap 이내  AND  내 속도가
    #         제한속도 × blocked_speed_frac 미만 (= 막혀서 느린 중)
    # 왜 필요한가: 속도 보상만으로는 "변경의 이득"이 미래에 분산되어
    #   도착하는 데다, 막힘 상태 자체가 드물어(스텝의 ~5%) 학습 신호가
    #   너무 희박하다 (실측: 12업데이트에도 막힘 상태와 일반 상태의
    #   변경확률이 분화되지 않음). 이 페널티는 "유지 = 매 스텝 감점,
    #   변경으로 탈출 = 감점 즉시 중단"이라는 즉각적 차등을 만들어
    #   정확히 그 상태에서 차선변경을 배우게 한다.
    "blocked_penalty": 0.05,     # 막힘 상태 스텝당 감점 (0이면 비활성)
    "blocked_gap": 20.0,         # 앞차가 이 거리(m) 이내면 "막힘" 후보
    "blocked_speed_frac": 0.7,   # 그리고 내 속도 < 지금 차로 제한속도×이 값일 때만 (12팀 11/15: vmax  /  차로 제한속도)
                                 # 앞 신호(150 m 안)가 적 · 황색이면 막힘으로 보지 않는다 (신호 대기열)
                                 # (앞이 가까워도 빠르게 흐르면 막힘 아님)

    # ---- 차선변경 관련 (원본 Flow 코드의 lc_penalty / rl_action_penalty 대응) ----
    # ★ 커리큘럼: 두 페널티 모두 초기 학습에서는 0으로 둔다.
    #   실측(run_130630): 페널티 0.05 상태에서 p_lane_change가
    #   0.37 / 0.11로 단조 붕괴 : 시도의 상당수가 게이트에 막혀 -0.05,
    #   실행돼도 즉시 -0.05인 반면 추월 이득은 지연·분산되어 오므로
    #   "변경 = 손해"만 학습됨. 페널티 없이 추월을 먼저 배우게 하고,
    #   학습 후 지그재그가 과하면 0.02~0.05로 재도입할 것.
    "lane_change_penalty": 0.0,   # 차선변경이 "실행될 때마다" 감점.
                                   #   목적: 이득 없는 지그재그(웨빙) 억제.
                                   #   속도 보상(스텝당 최대 0.1)의 절반 수준이라,
                                   #   "변경해서 더 빨라질 때만 변경"하도록 유도.
                                   #   0으로 두면 자유롭게 바꾸는 정책이 나온다.
    "invalid_action_penalty": 0.0,  # 실행 불가능한 차선변경을 "명령"하면 감점.
                                     #   (맨 왼쪽에서 또 왼쪽, 교차로 내부 등)
                                     #   목적: 의미 없는 행동 출력 자체를 줄여
                                     #   행동 분포를 깔끔하게 만드는 정칙화.
    "stuck_penalty": 3.0,        # 비정상 정지로 종료될 때 감점. 11/16 본 학습 전 검토: 0이면 경로 차로를 놓쳐 차로 끝에
                                 # 서도 120 s 동안 0을 받다 0으로 끝나 "차로를 잘못 골랐다"는 신호가 거의 없다 (γ^240 ≈ 0.09).
                                 # 도착 보너스(2)보다 크고 충돌 · 신호 위반(5)보다 작게. 시범은 전부 도착이라 BC 가치 초기화와
                                 # 어긋나지 않는다. (경로 이탈 · 순간이동은 정책이 거의 만들지 않아 0 그대로)
    # 적색 신호에 정지선을 넘으면 에피소드 종료 (end_reason="red_light") + 이 감점.
    # AV는 수업 원본대로 SUMO가 신호에 세워 주지 않으므로(setSpeedMode 0) 신호 준수는 정책이 배워야 한다.
    # 충돌과 같은 크기 : 실제로 교차 방향 차 · 보행자와 부딪힐 수 있는 위반이다.
    "red_light_penalty": 5.0,
    # 경로 이탈로 종료될 때 감점 : 잘못된 차로 조기 종료(SIMULATION["wrong_lane_end_m"]) 포함.
    # 수업 자료 5 §7이 예로 든 "잘못된 차선 진입 · 경로 이탈 감점". 기본 0, 값은 training/train.py에서 정한다.
    "off_route_penalty": 0.0,
}
# 보상 스케일에 대한 메모 (수업에서 다뤄볼 만한 지점):
#   처음엔 speed_weight=1.0, collision=-10, arrival=+5 였는데,
#   400스텝 동안 스텝당 +1이 쌓이면 에피소드 리턴이 ~100까지 커진다.
#   그러면 (a) critic이 큰 값을 맞추느라 value_loss가 요동치고,
#          (b) "빨리 달리다 충돌(-10)" 이 "천천히 완주" 보다 이득이 되어
#              충돌 회피를 배울 유인이 약해진다.
#   그래서 속도 보상을 1/10로 줄여 리턴을 ~10 규모로 낮췄다.
#    /  보상의 절대값이 아니라 "항 사이의 상대 비율"이 정책을 결정한다는
#     점을 확인해보는 실험을 해보길 권장.
